package com.tarapickle.identity.infrastructure.security;
import com.nimbusds.jose.jwk.source.ImmutableSecret; import com.nimbusds.jose.proc.SecurityContext; import jakarta.servlet.http.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.core.convert.converter.Converter; import org.springframework.http.HttpMethod; import org.springframework.security.authentication.AbstractAuthenticationToken; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.oauth2.jwt.*; import org.springframework.security.oauth2.server.resource.authentication.*; import org.springframework.security.web.SecurityFilterChain; import org.springframework.web.cors.*; import javax.crypto.spec.SecretKeySpec; import java.nio.charset.StandardCharsets; import java.util.*;
import org.springframework.security.oauth2.core.DelegatingOAuth2TokenValidator;
@Configuration @EnableMethodSecurity public class SecurityConfiguration {
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder(12);} @Bean JwtEncoder jwtEncoder(@Value("${tarapickle.jwt.secret}")String s){return new NimbusJwtEncoder(new ImmutableSecret<SecurityContext>(key(s)));} @Bean JwtDecoder jwtDecoder(@Value("${tarapickle.jwt.secret}")String s,@Value("${tarapickle.jwt.issuer}")String issuer,@Value("${tarapickle.jwt.audience}")String aud){NimbusJwtDecoder d=NimbusJwtDecoder.withSecretKey(key(s)).macAlgorithm(org.springframework.security.oauth2.jose.jws.MacAlgorithm.HS256).build(); d.setJwtValidator(new DelegatingOAuth2TokenValidator<>(JwtValidators.createDefaultWithIssuer(issuer),new JwtClaimValidator<List<String>>("aud",a->a!=null&&a.contains(aud))));return d;} private SecretKeySpec key(String s){byte[] b=Arrays.copyOf(s.getBytes(StandardCharsets.UTF_8),32);return new SecretKeySpec(b,"HmacSHA256");}
 @Bean SecurityFilterChain chain(HttpSecurity h) throws Exception {String[] open={"/api/v1/auth/register","/api/v1/auth/verify-email","/api/v1/auth/resend-verification","/api/v1/auth/login","/api/v1/auth/refresh","/api/v1/auth/password/forgot","/api/v1/auth/password/reset","/v3/api-docs/**","/swagger-ui/**","/swagger-ui.html","/actuator/health/**"}; return h.csrf(c->c.disable()).cors(c->{}).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).headers(x->x.contentSecurityPolicy(c->c.policyDirectives("default-src 'self'"))).authorizeHttpRequests(a->a.requestMatchers(open).permitAll().requestMatchers(HttpMethod.GET,"/api/v1/facilities/**").permitAll().anyRequest().authenticated()).oauth2ResourceServer(o->o.jwt(j->j.jwtAuthenticationConverter(converter()))).build();}
 Converter<Jwt,? extends AbstractAuthenticationToken> converter(){JwtGrantedAuthoritiesConverter g=new JwtGrantedAuthoritiesConverter();g.setAuthoritiesClaimName("roles");g.setAuthorityPrefix("ROLE_");JwtAuthenticationConverter c=new JwtAuthenticationConverter();c.setJwtGrantedAuthoritiesConverter(g);return c;}
 @Bean CorsConfigurationSource cors(@Value("${tarapickle.cors.allowed-origins}")List<String> origins){CorsConfiguration c=new CorsConfiguration();c.setAllowedOrigins(origins);c.setAllowedMethods(List.of("GET","POST","PUT","PATCH","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("Authorization","Content-Type","X-Correlation-ID","Idempotency-Key"));UrlBasedCorsConfigurationSource s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;}
}
